function renderOverview(){const li=healthFromConnected('connected.lidar'),im=healthFromConnected('connected.imu'),ca=healthFromConnected('connected.camera'),es=bool(raw('connected.esc_feedback'))?'ok':(bool(raw('connected.esc_ready'))?'warn':'bad');const motion=bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed'));const loc=channelFresh('amcl',4)?'ok':(channelFresh('ekf_local',4)?'warn':'bad');const nv=bool(raw('system.nav2_ready'))?'ok':(channelFresh('nav2_runtime',5)?'warn':'bad');const ld=obj('lidar');healthCard('lidar',li,Number.isFinite(+ld.scan_rate_hz)?fmt(ld.scan_rate_hz,1)+' Hz / '+fmt(ld.valid_ratio_pct,1)+'% valid':'waiting /scan_nav');healthCard('imu',im,channelFresh('imu',3)?'data /imu/data fresh':'waiting /imu/data');healthCard('camera',ca,obj('camera_frame').source||'Astra Pro');healthCard('esc',es,bool(raw('connected.esc_feedback'))?'ACK fresh':'waiting ESC ACK');healthCard('localization',loc,channelFresh('amcl',4)?'AMCL pose fresh':'waiting /amcl_pose');healthCard('nav2',nv,bool(raw('system.nav2_ready'))?'planner/controller/BT present':'waiting Nav2 runtime');const states=[li,im,ca,es,loc,nv],score=Math.round(states.reduce((a,x)=>a+(x==='ok'?1:x==='warn'?.5:0),0)/states.length*100);$('readinessRing').style.setProperty('--pct',score);setText('readinessPct',score+'%');setText('readinessTitle',motion?'Vehicle motion-ready':score>=70?'Core runtime online, safety gates pending':'System commissioning / offline');setText('readinessDetail',motion?'Localization, Nav2 and actuator safety gates report ready.':'Periksa LiDAR, IMU, AMCL, Nav2, perception, dan ESC. Motion tetap fail-closed sampai gate aktual siap.');setText('overallChip',motion?'MOTION READY':'FAIL-CLOSED');$('overallChip').className='status-chip '+(motion?'':'waiting');const pose=channelFresh('amcl',5)?obj('amcl'):obj('ekf_local'),imu=obj('imu');setText('overviewSpeed',fmt(getPath(obj('esc_odom'),'v')??getPath(obj('ekf_local'),'v')));setText('overviewSteer',fmt(deg(raw('esc_steer_actual')),1));setText('overviewYaw',fmt(deg(getPath(pose,'yaw')??getPath(imu,'yaw_rad')),1));setText('goalStateBig',getPath(obj('goal_state'),'state')||'IDLE');setText('activeSourceBig','ACTUATOR: '+(getPath(obj('esc_mux'),'raw')||'--'));setText('lastUpdate',new Date().toLocaleTimeString('id-ID'));const cn=obj('cmd_nav'),cs=obj('cmd_autonomy_integrated'),cf=obj('cmd_final'),caa=obj('cmd_actuator');setText('pipeNav',fmt(cn.linear_x));setText('pipeSafety',fmt(cs.linear_x));setText('pipeFinal',fmt(cf.linear_x));setText('pipeActuator',fmt(caa.linear_x));history.push({t:Date.now(),nav:+cn.linear_x||0,final:+cf.linear_x||0,actual:+raw('esc_drive_actual')||0});while(history.length>180)history.shift();drawSpark();renderAlerts();}
function renderAlerts(){const a=[];if(bool(raw('system.estop')))a.push(['danger','Emergency stop ACTIVE']);if(bool(raw('perception_emergency')))a.push(['danger','Perception emergency stop ACTIVE']);if(!bool(raw('connected.esc_feedback')))a.push(['danger','ESC ACK belum fresh - motor command tidak dianggap ready']);if(!bool(raw('connected.lidar')))a.push(['warn','LiDAR /scan_nav belum fresh']);if(!bool(raw('connected.imu')))a.push(['warn','IMU /imu/data belum fresh']);if(!channelFresh('amcl',4))a.push(['warn','AMCL pose belum fresh']);if(!(bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed'))))a.push(['warn','Motion gate masih tertutup']);if((bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed')))&&bool(raw('connected.esc_feedback')))a.push(['ok','Core motion chain ready']);setText('alertCount',a.filter(x=>x[0]!=='ok').length);$('alerts').innerHTML=a.length?a.map(x=>'<div class="alert-item '+x[0]+'">'+escapeHtml(x[1])+'</div>').join(''):'<div class="empty-state">Tidak ada kondisi aktif.</div>';}
function drawSpark(){const c=$('speedSpark'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body);ctx.strokeStyle=css.getPropertyValue('--border2');ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(history.length<2)return;const max=Math.max(1,...history.flatMap(x=>[Math.abs(x.nav),Math.abs(x.final),Math.abs(x.actual)]));[['nav','--blue'],['final','--green'],['actual','--cyan']].forEach(([key,col])=>{ctx.strokeStyle=css.getPropertyValue(col);ctx.lineWidth=2;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h/2-(p[key]/max)*(h*.38);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
