function worldToPx(x,y,c,meta){const mx=(x-meta.origin_x)/meta.resolution,my=(y-meta.origin_y)/meta.resolution;const sx=c.width/meta.width,sy=c.height/meta.height;return [mx*sx,my*sy]}
function drawMap(){const c=$('mapCanvas');if(!c)return;const rect=c.getBoundingClientRect();if(rect.width>0){const dpr=Math.min(devicePixelRatio||1,2);const nw=Math.round(rect.width*dpr),nh=Math.round(rect.height*dpr);if(c.width!==nw||c.height!==nh){c.width=nw;c.height=nh}}const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle=document.body.classList.contains('light')?'#e7eeee':'#050b0d';ctx.fillRect(0,0,w,h);const m=obj('map_meta');if(!mapImage||!m.width||!m.height)return;const scale=Math.min(w/mapImage.width,h/mapImage.height),dw=mapImage.width*scale,dh=mapImage.height*scale,ox=(w-dw)/2,oy=(h-dh)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.drawImage(mapImage,0,0);ctx.restore();const trans=(x,y)=>{const px=(x-m.origin_x)/m.resolution, py=(y-m.origin_y)/m.resolution;return [ox+px*scale,oy+(m.height-py)*scale]};const css=getComputedStyle(document.body);function pathDraw(key,color,width){const pts=obj(key).points||[];if(pts.length<2)return;ctx.strokeStyle=css.getPropertyValue(color);ctx.lineWidth=width*(devicePixelRatio||1);ctx.beginPath();pts.forEach((p,i)=>{const [x,y]=trans(p[0],p[1]);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}pathDraw('nav_path','--blue',2);pathDraw('local_path','--cyan',2);const goal=obj('goal_pose');if(Number.isFinite(+goal.x)){const [x,y]=trans(goal.x,goal.y);ctx.fillStyle=css.getPropertyValue('--red');ctx.beginPath();ctx.arc(x,y,7*(devicePixelRatio||1),0,Math.PI*2);ctx.fill()}const pose=channelFresh('amcl',5)?obj('amcl'):obj('ekf_local');if(Number.isFinite(+pose.x)){const [x,y]=trans(pose.x,pose.y),r=8*(devicePixelRatio||1);ctx.save();ctx.translate(x,y);ctx.rotate(-(pose.yaw||0));ctx.fillStyle=css.getPropertyValue('--green');ctx.beginPath();ctx.moveTo(r*1.5,0);ctx.lineTo(-r,r);ctx.lineTo(-r,-r);ctx.closePath();ctx.fill();ctx.restore()}mapTransform.trans=trans}
$('mapCanvas').addEventListener('click',e=>{const m=obj('map_meta');if(!mapImage||!m.width)return;const c=$('mapCanvas'),rect=c.getBoundingClientRect(),dpr=c.width/rect.width,px=(e.clientX-rect.left)*dpr,py=(e.clientY-rect.top)*dpr,scale=Math.min(c.width/mapImage.width,c.height/mapImage.height),ox=(c.width-mapImage.width*scale)/2,oy=(c.height-mapImage.height*scale)/2;const mx=(px-ox)/scale,my=m.height-(py-oy)/scale;if(mx<0||my<0||mx>m.width||my>m.height)return;$('goalX').value=(m.origin_x+mx*m.resolution).toFixed(2);$('goalY').value=(m.origin_y+my*m.resolution).toFixed(2)});
