function passText(v){return v===true?'PASS':v===false?'WAIT':'--'}
function renderCalibration(){const steering=findDeep(configData('vehicle'),'steering_calibration_valid'),circle=findDeep(configData('vehicle'),'steering_circle_calibration_valid'),drive=findDeep(configData('vehicle'),'drive_odometry_calibration_valid'),imuValid=findDeep(configData('imu'),'stationary_calibration_valid'),cameraMetric=findDeep(configData('perception'),'camera_metric_calibration_validated');setText('calSteeringFlag',passText(steering));setText('calCircleFlag',passText(circle));setText('calDriveFlag',passText(drive));setText('calImuFlag',passText(imuValid));const amclFresh=channelFresh('amcl',4),navReady=bool(raw('system.nav2_ready')),motion=bool(raw('system.motion_ready'))||bool(raw('system.autonomy_motion_allowed'));setChip('calLocChip',amclFresh,'AMCL FRESH','WAIT');setText('calLocMode',amclFresh?'AMCL + saved map':'WAIT');setText('calAmclFresh',amclFresh?'FRESH':'STALE / WAIT');setText('calPlanningReady',navReady?'READY':'WAIT');setText('calMotionReady',motion?'ALLOWED':'LOCKED');const steerReady=bool(raw('esc_calibration_controller_ready'));setChip('calSteerChip',steering===true&&steerReady,'CALIBRATED','WAIT');setText('calSteerController',steerReady?'READY':'WAIT');setText('calSteerTarget',fmt(deg(raw('esc_steer_target')),2)+'°');setText('calSteerActual',fmt(deg(raw('esc_steer_actual')),2)+'°');setText('calSteerProtocol',fmt(deg(raw('esc_steer_feedback_raw')),2)+'°');const cam=bool(raw('connected.camera')),healthy=bool(raw('camera_healthy')),fresh=channelFresh('camera_frame',3);setChip('calCameraChip',cameraMetric===true&&healthy,'VALIDATED','WAIT');setText('calCameraUsb',cam?'CONNECTED':'OFFLINE');setText('calCameraHealth',healthy?'HEALTHY':'WAIT');setText('calCameraMetric',passText(cameraMetric));setText('calPerceptionFresh',fresh?'FRESH':'STALE / WAIT');const im=obj('imu');setChip('calImuChip',imuValid===true&&bool(raw('connected.imu')),'VALIDATED','WAIT');setText('calImuUsb',bool(raw('connected.imu'))?'CONNECTED':'OFFLINE');setText('calImuStationary',passText(imuValid));setText('calImuYaw',fmt(deg(im.yaw_rad),2)+'°');setText('calImuGz',fmt(im.gz,4)+' rad/s');}
function drawTuneSpark(){const c=$('tuneSpark');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const css=getComputedStyle(document.body);ctx.strokeStyle=css.getPropertyValue('--border2');ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();if(history.length<2)return;const max=Math.max(.2,...history.flatMap(x=>[Math.abs(x.final),Math.abs(x.actual)]));[['final','--green'],['actual','--cyan']].forEach(([key,col])=>{ctx.strokeStyle=css.getPropertyValue(col);ctx.lineWidth=2;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h/2-(p[key]/max)*(h*.40);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
function renderTuning(){setText('tuneMppiReady',bool(raw('mppi_closed_loop_ready'))?'READY':'WAIT');setText('tuneSmoother',bool(raw('smoother_closed_loop_eligible'))?'ELIGIBLE':'WAIT');setText('tuneVelErr',fmt(raw('mppi_velocity_error'),3)+' m/s');setText('tuneSteerErr',fmt(deg(raw('mppi_steering_error')),2)+'°');setText('tuneNavCmd',fmt(obj('cmd_nav').linear_x,3)+' m/s');setText('tuneFinalCmd',fmt(obj('cmd_final').linear_x,3)+' m/s');setText('tuneDriveTarget',fmt(raw('esc_drive_target'),3)+' m/s');setText('tuneDriveActual',fmt(raw('esc_drive_actual'),3)+' m/s');setText('tuneSteerTarget',fmt(deg(raw('esc_steer_target')),2)+'°');setText('tuneSteerActual',fmt(deg(raw('esc_steer_actual')),2)+'°');setText('tuneQualification',pretty({mppi:obj('mppi_status'),smoother:obj('smoother_qualification'),velocity_error_mps:raw('mppi_velocity_error'),steering_error_rad:raw('mppi_steering_error'),yaw_rate_error_rps:raw('mppi_yaw_error')}));setText('tuneNavConfig',pretty(configData('nav2')));setText('tuneVehicleConfig',pretty({vehicle:configData('vehicle'),esc:configData('esc'),teleop:configData('teleop')}));drawTuneSpark()}
function currentWarnings(){let n=0;if(bool(raw('system.estop')))n++;if(!bool(raw('connected.esc_feedback')))n++;if(!bool(raw('connected.lidar')))n++;if(!bool(raw('connected.imu')))n++;if(!bool(raw('system.motion_ready')))n++;return n}
function renderReports(){const keys=Object.keys(state),fresh=keys.filter(k=>age(k)<3).length;setText('reportChannels',keys.length);setText('reportFresh',fresh);setText('reportWarnings',currentWarnings());setText('reportTimestamp','Snapshot '+new Date().toLocaleString('id-ID'));setText('reportSnapshot',pretty({goal:obj('goal_state'),pose:obj('amcl'),lidar:obj('lidar'),imu:obj('imu'),esc:{status:obj('esc_status'),target:raw('esc_drive_target'),actual:raw('esc_drive_actual')},perception:obj('perception_performance'),safety:{motion_ready:raw('system.motion_ready'),estop:raw('system.estop')}}))}
function downloadBlob(name,type,text){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function stamp(){return new Date().toISOString().replace(/[:.]/g,'-')}
function csvCell(v){const s=typeof v==='string'?v:JSON.stringify(v);return '"'+String(s??'').replace(/"/g,'""')+'"'}
function exportSummaryCsv(){const rows=[['channel','value','age_s'],...Object.keys(state).sort().map(k=>[k,textish(state[k]),Number.isFinite(age(k))?age(k).toFixed(3):''])];downloadBlob('adv_runtime_'+stamp()+'.csv','text/csv;charset=utf-8',rows.map(r=>r.map(csvCell).join(',')).join('\n'))}
function renderDiagnostics(){setText('diagChannels',Object.keys(state).length);setText('diagLatency',Math.abs(serverDelta)+' ms');setText('diagReadOnly',obj('server').read_only?'READ ONLY':'CONTROL');setText('webAction',pretty(obj('web_action')));setText('rawState',JSON.stringify(state,null,2));const keys=['system.autonomy_ready','system.motion_ready','system.nav2_ready','connected.lidar','connected.imu','connected.camera','connected.esc_ready','connected.esc_feedback','amcl','lidar_driver_status','imu_driver_status','ekf_local_status','ekf_global_status','trajectory_safety_state','collision_monitor_state','esc_status'];$('diagnosticTable').innerHTML=keys.map(k=>`<div class="diag-row"><span>${escapeHtml(k)}</span><b>${age(k)<3?'LIVE':age(k)<10?'STALE':'WAIT'}</b><code>${escapeHtml(textish(raw(k)))}</code></div>`).join('')}
function renderTop(){const ros=obj('server').ros===true;setText('rosStatus',ros?'ONLINE':'WAIT');$('rosDot').style.background=ros?'var(--green)':'var(--amber)';const mot=bool(raw('system.motion_ready'));setText('motionStatus',mot?'READY':'LOCKED');$('motionDot').style.background=mot?'var(--green)':'var(--amber)';const e=bool(raw('system.estop'));setText('estopStatus',e?'ACTIVE':'CLEAR');$('estopPill').classList.toggle('active',e);setText('serverClock',new Date().toLocaleTimeString('id-ID'))}
function render(){renderTop();renderOverview();renderNavigation();renderPerception();renderSensors();renderEsc();renderCalibration();renderTuning();renderReports();renderDiagnostics()}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
