function experimentSortKey(id){const final=id.startsWith('F')?1:0;const nums=(id.match(/\d+/g)||[]).map(Number);return [final,...nums]}
function compareExperiment(a,b){const A=experimentSortKey(a.id),B=experimentSortKey(b.id);for(let i=0;i<Math.max(A.length,B.length);i++){const d=(A[i]??-1)-(B[i]??-1);if(d)return d}return a.id.localeCompare(b.id)}
function effectiveExperimentList(){return [...(experiments[currentExp]||[])].sort(compareExperiment)}
function tuningFieldsFor(x){const catalog=(x.parameterFields||[]).filter(p=>p.yamlFileKey||p.isGroundTruth);if(catalog.some(p=>p.yamlFileKey))return catalog;return WEB_TUNING[currentExp]?.[x.id]||[]}
function configValue(file,path){let n=configs[file]?.data;if(n==null)return undefined;for(const part of String(path||'').split('.').filter(Boolean)){if(Array.isArray(n)&&/^\d+$/.test(part))n=n[+part];else if(n&&typeof n==='object')n=n[part];else return undefined}return n}
function resolveMetricPath(path){if(!path)return undefined;if(path==='derived.cte_m')return derivedCte();if(path==='derived.endpoint_error_m')return derivedEndpoint();if(path==='derived.path_heading_error_rad')return derivedHeadingError();if(path==='derived.velocity_error_mps')return (+raw('esc_drive_actual')||0)-(+obj('cmd_final').linear_x||0);if(path==='derived.steering_error_rad')return (+raw('esc_steer_actual')||0)-(+raw('esc_steer_target')||0);if(Object.prototype.hasOwnProperty.call(state,path))return state[path];const parts=path.split('.');for(let n=parts.length-1;n>0;n--){const root=parts.slice(0,n).join('.');if(Object.prototype.hasOwnProperty.call(state,root)){let v=state[root];for(const p of parts.slice(n)){if(v==null)return undefined;v=v[p]}return v}}return undefined}
function currentPose(){const g=obj('ekf_global');if(Number.isFinite(+g.x))return g;const l=obj('ekf_local');return Number.isFinite(+l.x)?l:null}
function nearestPathInfo(){const pose=currentPose(),pts=obj('local_path').points||obj('nav_path').points||[];if(!pose||!pts.length)return null;let best=null;for(const p of pts){const d=Math.hypot((+p[0])-pose.x,(+p[1])-pose.y);if(!best||d<best.d)best={d,p}}return best}
function derivedCte(){return nearestPathInfo()?.d}
function derivedEndpoint(){const pose=currentPose(),goal=obj('goal_pose');if(!pose||!Number.isFinite(+goal.x))return undefined;return Math.hypot(pose.x-goal.x,pose.y-goal.y)}
function wrapPi(v){while(v>Math.PI)v-=2*Math.PI;while(v<-Math.PI)v+=2*Math.PI;return v}
function derivedHeadingError(){const pose=currentPose(),n=nearestPathInfo();if(!pose||!n||!Number.isFinite(+n.p[2]))return undefined;return wrapPi((pose.yaw||0)-(+n.p[2]))}
function captureLabTelemetry(){if(!selectedExperiment)return;const now=Date.now(),paths=new Set(Object.values(selectedExperiment.liveSeries||{}));['esc_drive_target','esc_drive_actual','esc_steer_target','esc_steer_actual','imu.gz','lidar.range_center_m','lidar.valid_ratio_pct','lidar.scan_rate_hz','perception_performance.fps','foc_telemetry.iq_a','foc_telemetry.id_a'].forEach(p=>paths.add(p));for(const path of paths){const v=resolveMetricPath(path);if(typeof v!=='number'||!Number.isFinite(v))continue;const a=metricHistory.get(path)||[];a.push({t:now,v});while(a.length>900)a.shift();metricHistory.set(path,a)}const g=selectedExperiment.graphs?.[selectedGraphIndex];if(g?.type==='scatter'){const xv=resolveMetricPath(g.xSeries),yv=resolveMetricPath(g.ySeries);if(Number.isFinite(+xv)&&Number.isFinite(+yv)){const key=`${currentExp}:${selectedExperiment.id}:${selectedGraphIndex}`,a=scatterHistory.get(key)||[];a.push({x:+xv,y:+yv});while(a.length>900)a.shift();scatterHistory.set(key,a)}}}
function visitedKey(){return `adv-visited-${currentExp}`}
function visitedSet(){try{return new Set(JSON.parse(localStorage.getItem(visitedKey())||'[]'))}catch(_){return new Set()}}
function markVisited(id){const s=visitedSet();s.add(id);localStorage.setItem(visitedKey(),JSON.stringify([...s]));renderChapterProgress()}
function renderChapterProgress(){const total=(experiments[currentExp]||[]).length,v=visitedSet().size,p=total?Math.min(100,Math.round(v/total*100)):0;setText('chapterProgressText',`${v} / ${total} dibuka`);setText('chapterProgressPct',p+'%');$('chapterProgressBar').style.width=p+'%'}
async function loadExperiments(){try{experiments=await (await fetch('/api/experiments',{cache:'no-store'})).json();setText('labLeafCount',Object.values(experiments).reduce((n,a)=>n+(a?.length||0),0));setText('navTestCount',(experiments.navigation||[]).length);setText('perTestCount',(experiments.perception||[]).length);setText('escTestCount',(experiments.steering||[]).length);renderExperimentList();const list=effectiveExperimentList();if(list.length)selectExperimentById(list[0].id)}catch(e){$('experimentList').innerHTML='<div class="empty-state">Catalog unavailable: '+escapeHtml(e.message)+'</div>'}}
function renderExperimentList(){const term=($('experimentSearch')?.value||'').trim().toLowerCase();const list=effectiveExperimentList().filter(x=>!term||`${x.id} ${x.section} ${x.groupTitle}`.toLowerCase().includes(term));const visited=visitedSet();let lastGroup='',html='';for(const x of list){const group=x.id.startsWith('F')?'FINAL THESIS DATASET':x.groupTitle||x.groupId||'BAB IV';if(group!==lastGroup){html+=`<div class="chapter-group"><span>${escapeHtml(group)}</span></div>`;lastGroup=group}html+=`<button class="experiment-item ${selectedExperiment?.id===x.id?'active':''}" data-id="${escapeHtml(x.id)}"><i>${visited.has(x.id)?'✓':'○'}</i><div><span>${escapeHtml(x.id)}</span><b>${escapeHtml(x.section||x.id)}</b><small>${(x.tableNames||[]).length} tabel • ${(x.graphCaptions||[]).length} grafik • ${tuningFieldsFor(x).filter(p=>p.yamlFileKey).length} parameter</small></div></button>`} $('experimentList').innerHTML=html||'<div class="empty-state">Tidak ada subbab yang cocok.</div>';qa('.experiment-item',$('experimentList')).forEach(e=>e.onclick=()=>selectExperimentById(e.dataset.id));setText('chapterDomainTitle',currentExp==='navigation'?'Navigasi':currentExp==='perception'?'Persepsi':'ESC / FOC');renderChapterProgress()}
function selectExperimentById(id){const x=(experiments[currentExp]||[]).find(v=>v.id===id);if(!x)return;selectedExperiment=x;selectedTableIndex=0;selectedGraphIndex=0;metricHistory.clear();scatterHistory.clear();markVisited(id);renderExperimentList();renderSelectedExperiment()}
function renderSelectedExperiment(){const x=selectedExperiment;if(!x)return;setText('experimentGroup',x.groupTitle||x.groupId||currentExp.toUpperCase());setText('experimentTitle',x.section||x.id);setText('experimentSubtitle',`${currentExp==='navigation'?'Navigasi':currentExp==='perception'?'Persepsi':'ESC / FOC'} • source catalog ${x.id} • data aktual ROS, tanpa dummy.`);setText('experimentTableBadge',`${(x.tableNames||[]).length} TABLE`);setText('experimentGraphBadge',`${(x.graphCaptions||[]).length} GRAPH`);setText('experimentRawMetadata',JSON.stringify(x,null,2));renderTuningFields();renderLabTabs();renderExperimentGraphs();renderExperimentTable();renderContextVisual();renderSourceAudit()}
function renderTuningFields(){const x=selectedExperiment,fields=tuningFieldsFor(x),readOnly=obj('server').read_only===true;setText('labYamlMode',readOnly?'LOCKED':'WRITE');if(!fields.length){$('tuningFields').innerHTML='<div class="empty-state">Subbab ini adalah validasi/ringkasan; tidak ada parameter yang boleh diubah pada tahap ini.</div>';return}let html='';fields.forEach((p,i)=>{const isYaml=!!p.yamlFileKey,ro=p.kind==='yaml_readonly'||p.locked||readOnly;const val=isYaml?configValue(p.yamlFileKey,p.yamlPath):(localRunValues[`${currentExp}:${x.id}:${p.key||p.label}`]??p.placeholder??'');const typ=p.kind==='bool'?'checkbox':p.kind==='int'||p.kind==='float'?'number':'text';const step=p.kind==='int'?'1':'any';const checked=typ==='checkbox'&&!!val;html+=`<div class="tuning-field ${ro?'readonly':''}"><div class="tuning-field-head"><label>${escapeHtml(p.label||p.key||'Parameter')}</label><span>${isYaml?escapeHtml(p.yamlFileKey):'RUN / GT'} ${ro?'• LOCKED':''}</span></div><div class="tuning-input-row">${typ==='checkbox'?`<label class="switch"><input id="tuneField-${i}" type="checkbox" ${checked?'checked':''} ${ro?'disabled':''}><i></i><b>${checked?'TRUE':'FALSE'}</b></label>`:`<input id="tuneField-${i}" type="${typ}" step="${step}" value="${escapeHtml(val??'')}" ${ro?'readonly':''}>`} ${ro?'':`<button class="param-save" data-field-index="${i}">${isYaml?'SAVE YAML':'SET'}</button>`}</div><code>${escapeHtml(p.yamlPath||p.key||'run identity')}</code>${p.help?`<small>${escapeHtml(p.help)}</small>`:''}</div>`});$('tuningFields').innerHTML=html;qa('.param-save',$('tuningFields')).forEach(b=>b.onclick=()=>saveTuningField(+b.dataset.fieldIndex));qa('.switch input',$('tuningFields')).forEach(e=>e.onchange=()=>{const b=q('b',e.parentElement);if(b)b.textContent=e.checked?'TRUE':'FALSE'})}
async function saveTuningField(i){const p=tuningFieldsFor(selectedExperiment)[i],el=$(`tuneField-${i}`);if(!p||!el)return;let value=p.kind==='bool'?el.checked:el.value;if(p.kind==='int')value=parseInt(value,10);if(p.kind==='float')value=parseFloat(value);if((p.kind==='int'||p.kind==='float')&&!Number.isFinite(value))return toast('Nilai numerik tidak valid',true);if(!p.yamlFileKey){localRunValues[`${currentExp}:${selectedExperiment.id}:${p.key||p.label}`]=value;toast('Nilai run/ground truth disimpan untuk sesi browser');return}confirmModal('Simpan parameter YAML',`${p.label}\n${p.yamlFileKey}:${p.yamlPath}\n→ ${String(value)}`,async()=>{try{const r=await fetch('/api/config/set',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_key:p.yamlFileKey,path:p.yamlPath,value})});const j=await r.json();toast(j.message||'YAML response',!r.ok);if(j.config?.files)configs=j.config.files;renderTuningFields();renderCalibration();renderTuning()}catch(e){toast('YAML save gagal: '+e.message,true)}})}
function renderLabTabs(){const x=selectedExperiment;$('tableTabs').innerHTML=(x.tableNames||[]).map((t,i)=>`<button class="${i===selectedTableIndex?'active':''}" data-table-index="${i}">${escapeHtml(t||`Tabel ${i+1}`)}</button>`).join('');qa('[data-table-index]',$('tableTabs')).forEach(b=>b.onclick=()=>{selectedTableIndex=+b.dataset.tableIndex;renderLabTabs();renderExperimentTable()});$('graphTabs').innerHTML=(x.graphCaptions||[]).map((g,i)=>`<button class="${i===selectedGraphIndex?'active':''}" data-graph-index="${i}">Grafik ${i+1}<span>${escapeHtml(g)}</span></button>`).join('');qa('[data-graph-index]',$('graphTabs')).forEach(b=>b.onclick=()=>{selectedGraphIndex=+b.dataset.graphIndex;renderLabTabs();renderExperimentGraphs()})}
function graphSeriesForCurrent(){const x=selectedExperiment,g=x?.graphs?.[selectedGraphIndex];if(g?.type==='scatter')return {scatter:g};const labels=g?.series?.length?g.series:Object.keys(x?.liveSeries||{});return {series:labels.map((label,i)=>({label,path:x.liveSeries?.[label]||label,color:LAB_COLORS[i%LAB_COLORS.length]}))}}
function renderExperimentGraphs(){const x=selectedExperiment;if(!x||!(x.graphCaptions||[]).length){$('experimentGraphs').innerHTML='<div class="empty-state">Subbab ini memang tidak memiliki grafik. Gunakan tabel/rekap sesuai metode pengujian.</div>';return}const caption=x.graphCaptions[selectedGraphIndex]||`Grafik ${selectedGraphIndex+1}`;$('experimentGraphs').innerHTML=`<div class="chart-card"><div class="chart-title"><b>${escapeHtml(caption)}</b><span id="chartDataStatus">WAITING DATA</span></div><canvas id="experimentChart" width="1400" height="420"></canvas><div id="chartLegend" class="chart-legend"></div></div>`;drawExperimentChart()}
function canvasFit(c,height=300){const r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(500,Math.round(r.width*dpr)),h=Math.round(height*dpr);if(c.width!==w||c.height!==h){c.width=w;c.height=h}return {ctx:c.getContext('2d'),w,h,dpr}}
function drawExperimentChart(){const c=$('experimentChart');if(!c||!selectedExperiment)return;const {ctx,w,h,dpr}=canvasFit(c,285),css=getComputedStyle(document.body);ctx.clearRect(0,0,w,h);ctx.fillStyle=css.getPropertyValue('--chart-bg')||'#071113';ctx.fillRect(0,0,w,h);const pad={l:55*dpr,r:18*dpr,t:22*dpr,b:35*dpr},spec=graphSeriesForCurrent();if(spec.scatter){const key=`${currentExp}:${selectedExperiment.id}:${selectedGraphIndex}`,pts=scatterHistory.get(key)||[];if(pts.length<2)return drawChartEmpty(ctx,w,h,'Menunggu pasangan data scatter '+spec.scatter.xSeries+' / '+spec.scatter.ySeries);let xs=pts.map(p=>p.x),ys=pts.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);if(xmin===xmax){xmin-=1;xmax+=1}if(ymin===ymax){ymin-=1;ymax+=1}drawGrid(ctx,w,h,pad,dpr,xmin,xmax,ymin,ymax);ctx.fillStyle=LAB_COLORS[0];for(const p of pts){const x=pad.l+(p.x-xmin)/(xmax-xmin)*(w-pad.l-pad.r),y=h-pad.b-(p.y-ymin)/(ymax-ymin)*(h-pad.t-pad.b);ctx.beginPath();ctx.arc(x,y,2.2*dpr,0,Math.PI*2);ctx.fill()}setText('chartLegend',`${spec.scatter.xSeries} ↔ ${spec.scatter.ySeries}`);setText('chartDataStatus',`${pts.length} POINTS`);return}const series=spec.series.map(s=>({...s,data:metricHistory.get(s.path)||[]})).filter(s=>s.data.length);if(!series.length)return drawChartEmpty(ctx,w,h,'Belum ada telemetry untuk grafik ini');const vals=series.flatMap(s=>s.data.map(p=>p.v)),times=series.flatMap(s=>s.data.map(p=>p.t)),tmin=Math.min(...times),tmax=Math.max(...times),vmin=Math.min(...vals),vmax=Math.max(...vals);const span=Math.max(.0001,vmax-vmin),lo=vmin-span*.12,hi=vmax+span*.12;drawGrid(ctx,w,h,pad,dpr,(tmin-tmax)/1000,0,lo,hi);for(const s of series){ctx.strokeStyle=s.color;ctx.lineWidth=2*dpr;ctx.beginPath();s.data.forEach((p,i)=>{const x=pad.l+(p.t-tmin)/Math.max(1,tmax-tmin)*(w-pad.l-pad.r),y=h-pad.b-(p.v-lo)/(hi-lo)*(h-pad.t-pad.b);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}$('chartLegend').innerHTML=series.map(s=>`<span><i style="background:${s.color}"></i>${escapeHtml(s.label)} <b>${fmt(s.data.at(-1)?.v,3)}</b></span>`).join('');setText('chartDataStatus',`${series.reduce((n,s)=>n+s.data.length,0)} SAMPLES`)}
function drawGrid(ctx,w,h,pad,dpr,xmin,xmax,ymin,ymax){ctx.strokeStyle='rgba(120,150,155,.16)';ctx.fillStyle='rgba(160,180,185,.7)';ctx.font=`${9*dpr}px ui-monospace`;for(let i=0;i<=4;i++){const y=pad.t+i/4*(h-pad.t-pad.b),v=ymax-i/4*(ymax-ymin);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(Number.isFinite(v)?v.toFixed(3):'--',4*dpr,y+3*dpr)}for(let i=0;i<=5;i++){const x=pad.l+i/5*(w-pad.l-pad.r),v=xmin+i/5*(xmax-xmin);ctx.beginPath();ctx.moveTo(x,pad.t);ctx.lineTo(x,h-pad.b);ctx.stroke();ctx.fillText(Number.isFinite(v)?v.toFixed(1):'--',x-10*dpr,h-10*dpr)}}
function drawChartEmpty(ctx,w,h,msg){ctx.fillStyle='rgba(140,165,170,.7)';ctx.font=`13px ui-monospace`;ctx.textAlign='center';ctx.fillText(msg,w/2,h/2);ctx.textAlign='left';setText('chartDataStatus','WAITING DATA');setText('chartLegend','Source akan aktif otomatis ketika ROS publish.')}
function metricStats(path){const a=metricHistory.get(path)||[];if(!a.length)return null;const v=a.map(p=>p.v),mean=v.reduce((x,y)=>x+y,0)/v.length,rmse=Math.sqrt(v.reduce((x,y)=>x+y*y,0)/v.length);return {last:v.at(-1),mean,rmse,min:Math.min(...v),max:Math.max(...v),std:Math.sqrt(v.reduce((x,y)=>x+(y-mean)**2,0)/v.length),count:v.length}}
function primaryMetricPath(){return Object.values(selectedExperiment?.liveSeries||{})[0]}
function inferColumnValue(col){const k=String(col).toLowerCase(),variation=$('runVariation').value,condition=$('runCondition').value;if(k.includes('variasi')||k==='set'||k.includes('parameter')||k.includes('threshold')||k.includes('frequency')||k.includes('alpha')||k.includes('radius')||k.includes('penalty')||k.includes('weight'))return variation;if(k.includes('kondisi')||k.includes('skenario'))return condition;if(k.includes('satel'))return fmt(resolveMetricPath('lidar.valid_samples'),0);if(k.includes('dop'))return fmt(resolveMetricPath('lidar.dropout_pct'),2);if(k.includes('hacc'))return fmt(resolveMetricPath('lidar.range_center_m'),2);if(k.includes('rpm feedback')||k.includes('drive actual'))return fmt(raw('esc_drive_actual'),3);if(k.includes('rpm perintah')||k.includes('drive target'))return fmt(raw('esc_drive_target'),3);if(k.includes('steering perintah'))return fmt(deg(raw('esc_steer_target')),2);if(k==='feedback'||k.includes('steering actual'))return fmt(deg(raw('esc_steer_actual')),2);if(k.includes('endpoint')||k.includes('error akhir')||k.includes('stop error'))return fmt(derivedEndpoint(),3);if(k.includes('cte'))return fmt(derivedCte(),3);if(k.includes('heading'))return fmt(deg(derivedHeadingError()),2);if(k.includes('fps'))return fmt(resolveMetricPath('perception_performance.fps'),2);if(k.includes('confidence'))return fmt(resolveMetricPath('raw_detections.mean_confidence'),3);if(k.includes('status')||k.includes('keputusan'))return 'LIVE';if(k.includes('rmse')){const st=metricStats(primaryMetricPath());return st?fmt(st.rmse,4):'--'}if(k.includes('std')){const st=metricStats(primaryMetricPath());return st?fmt(st.std,4):'--'}return '--'}
function renderExperimentTable(){const x=selectedExperiment,cols=x?.tableColumns?.[selectedTableIndex]||[];const table=$('experimentTable');if(!cols.length){table.querySelector('thead').innerHTML='';table.querySelector('tbody').innerHTML='<tr><td>Subbab ini tidak mendefinisikan tabel.</td></tr>';return}table.querySelector('thead').innerHTML='<tr>'+cols.map(c=>`<th>${escapeHtml(c)}</th>`).join('')+'</tr>';table.querySelector('tbody').innerHTML='<tr class="live-preview-row">'+cols.map(c=>`<td>${escapeHtml(inferColumnValue(c))}</td>`).join('')+'</tr>';setText('tableLiveHint',`Tabel ${selectedTableIndex+1}/${x.tableColumns.length} • preview live; CSV raw/summary tersimpan saat Stop`)}
function renderContextVisual(){if(!selectedExperiment)return;const map=$('contextMap'),cam=$('contextCamera'),esc=$('contextEsc');map.style.display=currentExp==='navigation'?'block':'none';cam.style.display=currentExp==='perception'?'block':'none';esc.style.display=currentExp==='steering'?'block':'none';setText('contextTitle',currentExp==='navigation'?'Map • Path • Robot':currentExp==='perception'?'Camera • YOLOPv2':'FOC • Steering • Drive');if(currentExp==='navigation')drawExperimentMap();else if(currentExp==='perception')updateLabCamera();else drawExperimentEsc();renderContextMetrics()}
function drawExperimentMap(){const c=$('expMapCanvas'),m=obj('map_meta');if(!c||!mapImage||!m.width){if($('expMapEmpty'))$('expMapEmpty').style.display='grid';return}const {ctx,w,h,dpr}=canvasFit(c,310),scale=Math.min(w/mapImage.width,h/mapImage.height),dw=mapImage.width*scale,dh=mapImage.height*scale,ox=(w-dw)/2,oy=(h-dh)/2;ctx.clearRect(0,0,w,h);ctx.fillStyle='#050b0d';ctx.fillRect(0,0,w,h);ctx.drawImage(mapImage,ox,oy,dw,dh);const tr=(x,y)=>[ox+((x-m.origin_x)/m.resolution)*scale,oy+(m.height-(y-m.origin_y)/m.resolution)*scale];function path(key,color,width){const pts=obj(key).points||[];if(pts.length<2)return;ctx.strokeStyle=color;ctx.lineWidth=width*dpr;ctx.beginPath();pts.forEach((p,i)=>{const [x,y]=tr(p[0],p[1]);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}path('nav_path','#4aa8ff',2);path('local_path','#54d6e8',2);const pose=currentPose();if(pose){const [x,y]=tr(pose.x,pose.y);ctx.fillStyle='#48e0a4';ctx.beginPath();ctx.arc(x,y,7*dpr,0,Math.PI*2);ctx.fill()}const goal=obj('goal_pose');if(Number.isFinite(+goal.x)){const [x,y]=tr(goal.x,goal.y);ctx.strokeStyle='#ff7b8a';ctx.lineWidth=2*dpr;ctx.beginPath();ctx.arc(x,y,8*dpr,0,Math.PI*2);ctx.stroke()}$('expMapEmpty').style.display='none'}
function updateLabCamera(){if(currentExp!=='perception'||!$('expCameraImage'))return;if(!bool(raw('connected.camera'))){$('expCameraEmpty').style.display='grid';return}const im=new Image(),src='/api/camera.jpg?lab='+Date.now();im.onload=()=>{$('expCameraImage').src=src;$('expCameraImage').style.display='block';$('expCameraEmpty').style.display='none'};im.onerror=()=>{$('expCameraEmpty').style.display='grid'};im.src=src}
function drawExperimentEsc(){const c=$('expEscCanvas');if(!c)return;const {ctx,w,h,dpr}=canvasFit(c,310),cx=w/2;ctx.clearRect(0,0,w,h);ctx.fillStyle='#071113';ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(130,160,165,.25)';ctx.lineWidth=2*dpr;ctx.beginPath();ctx.moveTo(60*dpr,110*dpr);ctx.lineTo(w-60*dpr,110*dpr);ctx.stroke();const target=deg(raw('esc_steer_target'))||0,actual=deg(raw('esc_steer_actual'))||0,mapAngle=a=>cx+(Math.max(-45,Math.min(45,a))/45)*(w*.36);[['TARGET',target,'#ffc86b',85],['ACTUAL',actual,'#48e0a4',135]].forEach(([label,v,color,y])=>{ctx.fillStyle=color;ctx.fillRect(mapAngle(v)-3*dpr,y*dpr,6*dpr,48*dpr);ctx.font=`${11*dpr}px ui-monospace`;ctx.fillText(`${label} ${v.toFixed(2)}°`,18*dpr,(y+24)*dpr)});const foc=obj('foc_telemetry'),lines=[`Drive target ${fmt(raw('esc_drive_target'),3)} m/s`,`Drive actual ${fmt(raw('esc_drive_actual'),3)} m/s`,`Iq ${fmt(foc.iq_a??foc.iq,3)} A`,`Id ${fmt(foc.id_a??foc.id,3)} A`,`Vbus ${fmt(foc.vbus_v??foc.vbus,2)} V`];ctx.fillStyle='rgba(210,230,230,.82)';ctx.font=`${12*dpr}px ui-monospace`;lines.forEach((t,i)=>ctx.fillText(t,18*dpr,(210+i*22)*dpr))}
function renderContextMetrics(){let metrics=[];if(currentExp==='navigation')metrics=[['Pose X',fmt(currentPose()?.x,3)+' m'],['Pose Y',fmt(currentPose()?.y,3)+' m'],['CTE',fmt(derivedCte(),3)+' m'],['Endpoint',fmt(derivedEndpoint(),3)+' m'],['Path',fmt(obj('nav_path').length_m,2)+' m'],['Goal',obj('goal_state').state||'--']];else if(currentExp==='perception')metrics=[['Camera',bool(raw('connected.camera'))?'ONLINE':'OFF'],['Health',bool(raw('camera_healthy'))?'HEALTHY':'WAIT'],['FPS',fmt(resolveMetricPath('perception_performance.fps'),2)],['Objects',obj('object_points').count??'--'],['Lane',obj('lane_state').state||obj('lane_state').raw||'--'],['Near field',obj('near_field_state').state||obj('near_field_state').raw||'--']];else metrics=[['ESC',bool(raw('connected.esc_feedback'))?'ACK':'WAIT'],['Drive',fmt(raw('esc_drive_actual'),3)+' m/s'],['Steer',fmt(deg(raw('esc_steer_actual')),2)+'°'],['Error',fmt(deg(resolveMetricPath('derived.steering_error_rad')),2)+'°'],['Iq',fmt(resolveMetricPath('foc_telemetry.iq_a'),2)+' A'],['Mux',obj('esc_mux').raw||'--']];$('contextMetrics').innerHTML=metrics.map(([k,v])=>`<div><span>${escapeHtml(k)}</span><b>${escapeHtml(v)}</b></div>`).join('')}
function renderSourceAudit(){if(!selectedExperiment)return;const paths=[...new Set(Object.values(selectedExperiment.liveSeries||{}))],pills=paths.map(p=>{const v=resolveMetricPath(p),ok=v!==undefined&&v!==null;return `<span class="${ok?'ok':'wait'}"><i></i>${escapeHtml(p)}</span>`});$('sourceAvailability').innerHTML=pills.join('')||'<span class="wait"><i></i>No direct live-series binding; gunakan tabel/config evidence.</span>';const method=currentExp==='navigation'?'Nav2/localization telemetry + map/path + parameter YAML':currentExp==='perception'?'Camera/YOLOPv2 metrics + safety telemetry + parameter YAML':'ESC feedback + FOC telemetry + calibration/tuning YAML';setText('sourceMethod',method);setText('experimentSourceBadge',paths.some(p=>resolveMetricPath(p)!=null)?'LIVE SOURCE':'WAITING SOURCE')}
async function startWebRecording(){if(!selectedExperiment)return toast('Pilih subbab dulu',true);try{const r=await fetch('/api/experiment/record/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subsystem:currentExp,id:selectedExperiment.id,variation:$('runVariation').value,condition:$('runCondition').value,sample_rate_hz:+$('runSampleRate').value})});const j=await r.json();toast(j.message||'Recorder response',!r.ok);if(r.ok){recordStartedMs=Date.now();setRecordingUi(true,j.recording)}}catch(e){toast('Start CSV gagal: '+e.message,true)}}
async function stopWebRecording(){try{const r=await fetch('/api/experiment/record/stop',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const j=await r.json();toast(j.message||'Recorder response',!r.ok);setRecordingUi(false,j);if(r.ok){setText('recordPath','Raw: '+(j.raw_csv||'saved'));setText('recordMessage','Summary: '+(j.summary_csv||'')+' • Manifest: '+(j.manifest||''))}}catch(e){toast('Stop CSV gagal: '+e.message,true)}}
function setRecordingUi(active,info={}){$('startCsvBtn').disabled=active;$('stopCsvBtn').disabled=!active;setText('labRecorderState',active?'RECORDING':'IDLE');setText('recordChip',active?'RECORDING':'IDLE');$('recordChip').className='status-chip '+(active?'recording':'waiting');setText('labRecorderSamples',`${info.samples||0} samples`);if(!active){recordStartedMs=0;setText('recordElapsed','00:00.0')}}
async function pollRecorder(){try{const r=await fetch('/api/experiment/record/status',{cache:'no-store'}),j=await r.json();setRecordingUi(!!j.active,j);if(j.active&&!recordStartedMs&&j.started_at)recordStartedMs=Date.parse(j.started_at);if(j.active&&recordStartedMs){const sec=(Date.now()-recordStartedMs)/1000,min=Math.floor(sec/60);setText('recordElapsed',`${String(min).padStart(2,'0')}:${(sec-min*60).toFixed(1).padStart(4,'0')}`)}}catch(_){}}
$('startCsvBtn').onclick=startWebRecording;$('stopCsvBtn').onclick=stopWebRecording;$('refreshExperimentConfig').onclick=async()=>{await loadConfig();renderTuningFields();toast('YAML dimuat ulang')};$('experimentSearch').oninput=renderExperimentList;$('graphClearBtn').onclick=()=>{metricHistory.clear();scatterHistory.clear();renderExperimentGraphs()};
qa('.domain-tab').forEach(b=>b.onclick=()=>{qa('.domain-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentExp=b.dataset.exp;selectedExperiment=null;metricHistory.clear();scatterHistory.clear();renderExperimentList();const list=effectiveExperimentList();if(list.length)selectExperimentById(list[0].id)});
function renderLabWorkbench(){if(!selectedExperiment)return;captureLabTelemetry();if($('experimentChart'))drawExperimentChart();renderExperimentTable();renderContextVisual();renderSourceAudit()}
setInterval(renderLabWorkbench,350);setInterval(pollRecorder,1000);setInterval(updateLabCamera,900);

async function loadConfig(){try{const j=await (await fetch('/api/config',{cache:'no-store'})).json();configs=j.files||{};const keys=Object.keys(configs);$('configTabs').innerHTML=keys.map((k,i)=>`<button data-conf="${escapeHtml(k)}" class="${i?'':'active'}">${escapeHtml(k)}</button>`).join('');qa('[data-conf]',$('configTabs')).forEach(b=>b.onclick=()=>{qa('[data-conf]',$('configTabs')).forEach(x=>x.classList.remove('active'));b.classList.add('active');showConfig(b.dataset.conf)});if(keys[0])showConfig(keys[0]);renderCalibration();renderTuning();}catch(e){setText('configView','Config API unavailable: '+e.message)}}
function showConfig(k){const c=configs[k]||{};setText('configView',`# ${c.path||k}\n\n${JSON.stringify(c.data??c,null,2)}`)}
$('exportStateBtn').onclick=()=>downloadBlob('adv_telemetry_'+stamp()+'.json','application/json',JSON.stringify({exported_at:new Date().toISOString(),state,updated},null,2));$('exportConfigBtn').onclick=()=>downloadBlob('adv_config_'+stamp()+'.json','application/json',JSON.stringify(configs,null,2));$('exportExperimentsBtn').onclick=()=>downloadBlob('adv_bab4_catalog_'+stamp()+'.json','application/json',JSON.stringify(experiments,null,2));$('exportCsvBtn').onclick=exportSummaryCsv;$('printReportBtn').onclick=()=>window.print();$('refreshConfigBtn').onclick=loadConfig;$('refreshStateBtn').onclick=fullState;
setInterval(()=>{renderTop();if(mapImage&&q('#page-navigation.active'))drawMap()},500);setInterval(updateCamera,700);setInterval(()=>{if(!mapImage||Date.now()-(obj('map_meta').at_ms||0)<3000)loadMapImage()},6000);
window.addEventListener('resize',()=>drawMap());connectSse();fullState();loadExperiments();loadConfig();loadMapImage();render();
